package mod.cdv.tnpc.tactical;
import java.util.*;import java.lang.ref.WeakReference;
/** Reactions use synced vanilla head rotations, crouch and off-hand gestures, never attacks. */
public final class Expression20 {
 static final Map<Object,Motion> MOTIONS=new WeakHashMap<>();static final Map<Object,Long> CHAT_AFTER=new WeakHashMap<>();static final Map<Object,Long> VOICE_AFTER=new WeakHashMap<>();
 static String reaction(Object n,Object p,String topic){if(Set.of("insult","threaten","harm").contains(topic))return Social.kind(n)==2?"afraid":Social.kind(n)==0?"hostile":"angry";if(Set.of("thanks","favor_done","joined","treated").contains(topic))return "happy";return Identity20.attitude(n,p).equals("enemy")?"hostile":"calm";}
 static String current(Object n){String value=Social.s(Social.tag(n),"soc_reaction20");return Social.l(Social.tag(n),"soc_reaction_until20")>Social.time(n)&&!value.isEmpty()?value:"calm";}
 static void react(Object n,Object p,String topic){String mood=reaction(n,p,topic);long now=Social.time(n);Social.c(Social.tag(n),"putString","soc_reaction20",mood);Social.c(Social.tag(n),"putLong","soc_reaction_until20",now+60);if(!MOTIONS.containsKey(n)||now-MOTIONS.get(n).start>=12)MOTIONS.put(n,new Motion(now,mood,((Number)Social.c(n,"getXRot")).floatValue(),((Number)Social.c(n,"getYHeadRot")).floatValue(),Social.yes(Social.c(n,"isShiftKeyDown"))));if(Set.of("greet","joined","harm","treated").contains(topic)&&now>=VOICE_AFTER.getOrDefault(n,0L)){SpeechSounds20.play(n,mood);VOICE_AFTER.put(n,now+300);}if(Set.of("thanks","favor_done","joined","treated","insult","threaten","harm").contains(topic))chat(n,topic.equals("insult")||topic.equals("threaten")||topic.equals("harm")?"bad_action":"good_action",p,false);}
 static void tick(Object n,Social.Memory memory,long now)throws Exception{Motion motion=MOTIONS.get(n);if(motion!=null){boolean safe=CalmBrain.state(n).target==null&&memory.medicalUntil<=now&&memory.fearUntil<=now&&!CompanionInventory.active(n);if(!safe||now-motion.start>=36){MOTIONS.remove(n);if(safe){Social.c(n,"setXRot",motion.pitch);Social.c(n,"setYHeadRot",motion.head);CalmBrain.crouch(n,motion.crouch);}}else{long t=now-motion.start;boolean angry=motion.mood.equals("angry")||motion.mood.equals("hostile");float nod=(float)Math.sin(t*Math.PI/9)*(motion.mood.equals("happy")?14:5);Social.c(n,"setXRot",motion.pitch+(angry?-4:nod));Social.c(n,"setYHeadRot",motion.head+(angry?(float)Math.sin(t*Math.PI/6)*17:0));if(motion.mood.equals("happy")||motion.mood.equals("afraid"))CalmBrain.crouch(n,motion.mood.equals("afraid")||t/6%2==0);if((motion.mood.equals("happy")||angry||motion.mood.equals("afraid"))&&(t==0||t==12))Social.c(n,"swing",SocialR.get(Social.t("net.minecraft.world.InteractionHand"),"OFF_HAND"));}}
  if(now<memory.chatterAt)return;memory.chatterAt=now+(Social.persona(n)==7?1800:900)+Math.floorMod(Social.uuid(n).hashCode()+(int)(now/20),901);if(Conversation.busy(n))return;List<?> people=Social.nearby(n,Social.PLAYER,12);if(people.isEmpty())return;for(Object p:people){if(!listener(n,p)||now<CHAT_AFTER.getOrDefault(p,0L))continue;String relation=Identity20.attitude(n,p);if(relation.equals("enemy")&&CalmBrain.state(n).target!=p)continue;String topic=relation.equals("enemy")?"enemy":memory.threats>=4?"horde":memory.mood.equals("wounded")?"wounded":Social.kind(n)==2&&Social.armed(p)?"afraid":Social.num(Social.c(Social.world(n),"getDayTime"))%24000>=13000?"night":Social.yes(Social.c(Social.world(n),"isRaining"))?"rain":relation.equals("friendly")?"friendly":"neutral";if(chat(n,topic,p,true)){break;}}
 }
 static boolean listener(Object n,Object p){return Social.alive(p)&&Social.world(n)==Social.world(p)&&Social.distance(n,p)<=144&&!Social.yes(Social.c(p,"isSpectator"))&&Social.visible(n,p);}
 static boolean chat(Object n,String topic,Object focus,boolean ambient){boolean sent=false;long now=Social.time(n);int variant=Math.floorMod(Social.uuid(n).hashCode()+(int)(now/20),4);for(Object p:Social.nearby(n,Social.PLAYER,12)){if(!listener(n,p)||now<CHAT_AFTER.getOrDefault(p,0L))continue;Object speech=Social.c(Social.t("net.minecraft.network.chat.Component"),"translatable","dialog.soc.ambient."+topic+"."+variant,new Object[0]);Object label=Social.c(Social.t("net.minecraft.network.chat.Component"),"translatable","soc.attitude."+Identity20.attitude(n,p),new Object[0]);Social.say(p,"soc.chat.named",Identity20.name(n),label,speech);CHAT_AFTER.put(p,now+(ambient?400:160));sent=true;}return sent;}
 static final class Motion{final long start;final String mood;final float pitch,head;final boolean crouch;Motion(long s,String m,float p,float h,boolean c){start=s;mood=m;pitch=p;head=h;crouch=c;}}
}
